#ifndef DISKIMG_H
#define DISKIMG_H

// CP/M disk images built into the firmware, compressed (lz.h), to start an
// SD card with: diskimg_install writes one to /DISKS80/<name>.DSK. The
// table is generated by src/disks/diskimg_gen.py (src/disks/diskimg.cmake). Portable
// C (FatFs), host-tested.

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#ifndef DISKIMG_IN_FLASH
#define DISKIMG_IN_FLASH 0
#endif

typedef struct {
	const char *name;    // 8.3 base name, upper case: "CPM22"
	uint32_t size;       // bytes, uncompressed
	uint32_t crc;        // CRC-32 of the uncompressed image
	const uint8_t *data; // compressed; in flash in the firmware
	uint32_t data_len;
} diskimg_t;

extern const diskimg_t diskimg_list[];
extern const unsigned diskimg_count;

typedef enum {
	DISKIMG_WRITTEN,
	DISKIMG_EXISTS,  // left as it was (overwrite not asked for)
	DISKIMG_FAILED,  // FatFs error, or the data did not check out
} diskimg_result_t;

// The image named name (case-insensitive), or NULL.
const diskimg_t *diskimg_find(const char *name);

// Progress of an install: done of total bytes written.
typedef void (*diskimg_progress_t)(void *ctx, uint32_t done, uint32_t total);

// Write img to /DISKS80/<name>.DSK on the mounted FatFs volume, creating the
// directory if needed, unless the file exists and !overwrite. window is
// LZ_WINDOW bytes of scratch. A failed write removes the partial file.
// progress, if not NULL, is called after each chunk written.
diskimg_result_t diskimg_install(const diskimg_t *img, bool overwrite, uint8_t *window,
	diskimg_progress_t progress, void *ctx);

#endif
